BYTES = {'fp32': 4, 'fp16': 2, 'bf16': 2, 'int8': 1, 'int4': 0.5}


def model_memory_gb(params, precision):
    if precision not in BYTES:
        raise ValueError(f'unknown precision {precision}')
    if not isinstance(params, (int, float)) or params <= 0:
        raise ValueError('params must be positive')
    return round(params * BYTES[precision] / 10**9, 2)

def training_days(params, tokens, gpus, peak_flops, mfu):
    if gpus < 1 or not 0 < mfu <= 1:
        raise ValueError('need at least one GPU and 0 < mfu <= 1')
    seconds = 6 * params * tokens / (gpus * peak_flops * mfu)
    return round(seconds / 86400, 1)

def fit_line(xs, ys, lr, steps):
    w, b = 0.0, 0.0
    n = len(xs)
    for _ in range(steps):
        errors = [w * x + b - y for x, y in zip(xs, ys)]
        dw = sum(2 * e * x for e, x in zip(errors, xs)) / n
        db = sum(2 * e for e in errors) / n
        w -= lr * dw
        b -= lr * db
    return (round(w, 3) + 0.0, round(b, 3) + 0.0)

def make_batches(n, batch_size, drop_last=False):
    if batch_size < 1:
        raise ValueError('batch_size must be at least 1')
    batches = []
    for start in range(0, n, batch_size):
        end = min(start + batch_size, n)
        if drop_last and end - start < batch_size:
            break
        batches.append((start, end))
    return batches

import math


def scaled_lr(base_lr, base_batch, new_batch, rule='linear'):
    ratio = new_batch / base_batch
    if rule == 'linear':
        factor = ratio
    elif rule == 'sqrt':
        factor = math.sqrt(ratio)
    else:
        raise ValueError(f'unknown rule {rule}')
    return round(base_lr * factor, 6)

import math


def shard_indices(n, world_size, rank):
    if not 0 <= rank < world_size:
        raise ValueError('rank out of range')
    total = math.ceil(n / world_size) * world_size
    indices = list(range(n))
    while len(indices) < total:
        indices += indices[:total - len(indices)]
    return indices[rank::world_size]

def average_gradients(worker_grads):
    if not worker_grads or len({len(g) for g in worker_grads}) != 1:
        raise ValueError('need gradients of equal length')
    n = len(worker_grads)
    return [round(sum(vals) / n, 4) for vals in zip(*worker_grads)]

def all_reduce(vectors, op='sum'):
    if op == 'sum':
        combined = [sum(v) for v in zip(*vectors)]
    elif op == 'mean':
        combined = [round(sum(v) / len(vectors), 4) for v in zip(*vectors)]
    elif op == 'max':
        combined = [max(v) for v in zip(*vectors)]
    else:
        raise ValueError(f'unknown op {op}')
    return [list(combined) for _ in vectors]

def ring_cost(size_mb, workers):
    if workers < 1:
        raise ValueError('need at least one worker')
    p = workers
    return {'steps': 2 * (p - 1), 'sent_mb_per_worker': round(2 * (p - 1) / p * size_mb, 2)}

def accumulate(micro_grads, accum_steps):
    updates = []
    for i in range(0, len(micro_grads) - accum_steps + 1, accum_steps):
        group = micro_grads[i:i + accum_steps]
        updates.append([round(sum(v) / accum_steps, 4) for v in zip(*group)])
    return updates

def accum_steps_needed(target_batch, micro_batch, gpus):
    if min(target_batch, micro_batch, gpus) < 1:
        raise ValueError('all arguments must be at least 1')
    per_step = micro_batch * gpus
    if target_batch % per_step:
        raise ValueError('target batch is not a multiple of micro_batch x gpus')
    return target_batch // per_step

def fp16_status(x):
    if abs(x) > 65504:
        return 'OVERFLOW'
    if x != 0 and abs(x) < 2 ** -24:
        return 'UNDERFLOW'
    return 'OK'

class LossScaler:
    def __init__(self, scale=65536.0, growth_interval=2000):
        self.scale = scale
        self.growth_interval = growth_interval
        self.good_steps = 0

    def update(self, found_overflow):
        if found_overflow:
            self.scale = max(1.0, self.scale / 2)
            self.good_steps = 0
            return False
        self.good_steps += 1
        if self.good_steps >= self.growth_interval:
            self.scale *= 2
            self.good_steps = 0
        return True

BYTES_PER_PARAM = {'adam_mixed': 16, 'adam_fp32': 16, 'sgd_momentum_fp32': 12, 'inference_fp16': 2}


def training_memory_gb(params, setup):
    if setup not in BYTES_PER_PARAM:
        raise ValueError(f'unknown setup {setup}')
    return round(params * BYTES_PER_PARAM[setup] / 1e9, 1)

def fits_on_gpu(params, batch, seq_len, hidden, layers, gpu_gb):
    states = round(16 * params / 1e9, 1)
    acts = round(batch * seq_len * hidden * layers * 34 / 1e9, 1)
    total = round(states + acts, 1)
    return {'states_gb': states, 'activations_gb': acts, 'total_gb': total, 'fits': total <= gpu_gb}

def zero_memory_gb(params, gpus, stage):
    if stage == 0:
        b = 16 * params
    elif stage == 1:
        b = 4 * params + 12 * params / gpus
    elif stage == 2:
        b = 2 * params + 14 * params / gpus
    elif stage == 3:
        b = 16 * params / gpus
    else:
        raise ValueError('stage must be 0, 1, 2 or 3')
    return round(b / 1e9, 1)

def fsdp_schedule(layers):
    events = []
    for layer in layers:
        events += [f'gather:{layer}', f'forward:{layer}', f'free:{layer}']
    for layer in reversed(layers):
        events += [f'gather:{layer}', f'backward:{layer}', f'reduce_scatter:{layer}', f'free:{layer}']
    return events

def col_parallel_matmul(x, W, parts):
    cols = len(W[0]) // parts
    output = []
    for k in range(parts):
        for j in range(k * cols, (k + 1) * cols):
            output.append(sum(x[i] * W[i][j] for i in range(len(x))))
    return (output, cols)

def row_parallel_matmul(x, W, parts):
    rows = len(x) // parts
    cols = len(W[0])
    partials = []
    for k in range(parts):
        part = [sum(x[i] * W[i][j] for i in range(k * rows, (k + 1) * rows)) for j in range(cols)]
        partials.append(part)
    output = [sum(p[j] for p in partials) for j in range(cols)]
    return (output, partials)

def bubble_fraction(stages, micro_batches):
    return round((stages - 1) / (micro_batches + stages - 1), 3)


def micro_batches_for(stages, max_bubble):
    m = 1
    while (stages - 1) / (m + stages - 1) > max_bubble:
        m += 1
    return m

def gpipe_forward(stages, micro_batches):
    timeline = []
    for t in range(micro_batches + stages - 1):
        row = []
        for s in range(stages):
            k = t - s + 1
            row.append(k if 1 <= k <= micro_batches else None)
        timeline.append(row)
    return timeline

def activation_memory(layers, per_layer_gb, every=None):
    if every is None:
        return round(layers * per_layer_gb, 2)
    if layers % every:
        raise ValueError('every must divide layers')
    return round((layers / every + every) * per_layer_gb, 2)

def best_interval(layers):
    best = None
    for k in range(1, layers + 1):
        if layers % k == 0:
            cost = layers / k + k
            if best is None or cost < best[0]:
                best = (cost, k)
    return best[1]

def momentum_step(w, g, v, lr, beta):
    new_w, new_v = [], []
    for wi, gi, vi in zip(w, g, v):
        vn = beta * vi + gi
        new_v.append(round(vn, 6))
        new_w.append(round(wi - lr * vn, 6))
    return (new_w, new_v)

import math


def lr_at(step, max_lr, warmup, total, min_lr=0.0):
    if step < warmup:
        lr = max_lr * (step + 1) / warmup
    elif step >= total:
        lr = min_lr
    else:
        progress = (step - warmup) / (total - warmup)
        lr = min_lr + 0.5 * (max_lr - min_lr) * (1 + math.cos(math.pi * progress))
    return round(lr, 8)

def step_decay(step, base_lr, drop, every):
    return round(base_lr * drop ** (step // every), 8)


def schedule(steps, base_lr, drop, every):
    return [(s, step_decay(s, base_lr, drop, every)) for s in range(0, steps, every)]

