def clip_by_global_norm(grads, max_norm):
    norm = math.sqrt(sum(v * v for layer in grads for v in layer))
    scale = max_norm / norm if norm > max_norm else 1.0
    return ([[round(v * scale, 4) for v in layer] for layer in grads], round(norm, 4))

import math


def first_instability(losses, window=3, factor=2.0):
    for i, loss in enumerate(losses):
        if math.isnan(loss):
            return i
        if i >= window:
            mean = sum(losses[i - window:i]) / window
            if loss > factor * mean:
                return i
    return None

import json

REQUIRED = ('step', 'weights', 'optimizer', 'seed')


def save_checkpoint(step, weights, optimizer_state, seed):
    return json.dumps({'version': 1, 'step': step, 'weights': weights, 'optimizer': optimizer_state, 'seed': seed},
                      sort_keys=True)


def load_checkpoint(text):
    data = json.loads(text)
    if data.get('version') != 1:
        raise ValueError('unsupported checkpoint version')
    missing = [k for k in REQUIRED if k not in data]
    if missing:
        raise ValueError(f'checkpoint is missing {missing}')
    return data

def elastic_plan(global_batch, micro_batch, gpus):
    for n in range(gpus, 0, -1):
        if global_batch % (micro_batch * n) == 0:
            return {'gpus': n, 'accum_steps': global_batch // (micro_batch * n)}
    raise ValueError('global batch cannot be split into micro-batches')

def lost_work(fail_step, checkpoint_every, step_seconds, restart_seconds):
    resume = fail_step // checkpoint_every * checkpoint_every
    lost = fail_step - resume
    return {'resume_from': resume, 'lost_steps': lost,
            'lost_minutes': round((lost * step_seconds + restart_seconds) / 60, 1)}

def allreduce_ms(size_mb, gpus, latency_us, bandwidth_gbps):
    if gpus <= 1:
        return 0.0
    chunk_ms = latency_us / 1000 + (size_mb / gpus) * 8 / (bandwidth_gbps * 1000) * 1000
    return round(2 * (gpus - 1) * chunk_ms, 2)

def make_buckets(layer_sizes_mb, bucket_mb):
    buckets, current, total = [], [], 0
    for i in reversed(range(len(layer_sizes_mb))):
        size = layer_sizes_mb[i]
        if current and total + size > bucket_mb:
            buckets.append(current)
            current, total = [], 0
        current.append(i)
        total += size
    if current:
        buckets.append(current)
    return buckets

def step_time(compute_ms, comm_ms):
    compute_done = comm_done = 0
    for c, m in zip(compute_ms, comm_ms):
        compute_done += c
        comm_done = max(comm_done, compute_done) + m
    sequential = sum(compute_ms) + sum(comm_ms)
    return {'overlapped': comm_done, 'sequential': sequential,
            'saved_pct': round((sequential - comm_done) / sequential * 100, 1)}

import math


def chinchilla(compute_flops):
    n = math.sqrt(compute_flops / 120)
    return {'params_b': round(n / 1e9, 1), 'tokens_b': round(20 * n / 1e9, 1)}

def budget_report(params, tokens, gpu_peak_flops, mfu, price_per_gpu_hour):
    flops = 6 * params * tokens
    hours = int(round(flops / (gpu_peak_flops * mfu) / 3600))
    tpp = round(tokens / params, 1)
    verdict = 'UNDERTRAINED' if tpp < 15 else 'OVERTRAINED' if tpp > 100 else 'BALANCED'
    return {'flops': flops, 'gpu_hours': hours, 'cost': int(round(hours * price_per_gpu_hour)),
            'tokens_per_param': tpp, 'verdict': verdict}

import statistics


def throughput_report(step_seconds, tokens_per_step):
    median = statistics.median(step_seconds)
    return {
        'tokens_per_sec': int(round(tokens_per_step * len(step_seconds) / sum(step_seconds))),
        'median_step': round(median, 3),
        'slowest_step': round(max(step_seconds), 3),
        'slow_steps': sum(t > 1.5 * median for t in step_seconds),
    }

def top_phase(profile):
    if not profile:
        return (None, 0.0)
    name = min(profile, key=lambda k: (-profile[k], k))
    return (name, round(profile[name] / sum(profile.values()) * 100, 1))

ADVICE = {
    'INPUT_BOUND': 'add data loader workers and prefetch',
    'COMM_BOUND': 'overlap communication or increase batch per GPU',
    'COMPUTE_BOUND': 'use mixed precision and fused kernels',
}


def classify_step(data_wait_ms, compute_ms, comm_ms):
    total = data_wait_ms + compute_ms + comm_ms
    if data_wait_ms > 0.2 * total:
        return 'INPUT_BOUND'
    if comm_ms > compute_ms:
        return 'COMM_BOUND'
    return 'COMPUTE_BOUND'


def advice(kind):
    return ADVICE[kind]

def apply_capacity(assignments, experts, capacity):
    load = [0] * experts
    dropped = []
    for i, e in enumerate(assignments):
        if load[e] < capacity:
            load[e] += 1
        else:
            dropped.append(i)
    mean = sum(load) / experts
    return {'load': load, 'dropped': dropped, 'imbalance': round(max(load) / mean, 2) if mean else 0.0}

def lora_params(layers, d_in, d_out, rank):
    full = layers * d_in * d_out
    lora = layers * rank * (d_in + d_out)
    return {'full': full, 'lora': lora, 'trainable_pct': round(lora / full * 100, 3)}

def quantize(values):
    peak = max(abs(v) for v in values)
    scale = peak / 127 if peak else 1.0
    q = [max(-127, min(127, round(v / scale))) for v in values]
    return (q, round(scale, 6))


def dequantize(q, scale):
    return [round(qi * scale, 4) + 0.0 for qi in q]

def model_size_gb(params, bits):
    return round(params * bits / 8 / 1e9, 1)


def max_error(values):
    scale = max(abs(v) for v in values) / 127
    return round(max(abs(v - round(v / scale) * scale) for v in values), 4)

def place_job(gpus_needed, free_gpus):
    if sum(free_gpus) < gpus_needed:
        return None
    fits = [i for i, f in enumerate(free_gpus) if f >= gpus_needed]
    if fits:
        best = min(fits, key=lambda i: (free_gpus[i], i))
        return {best: gpus_needed}
    plan, left = {}, gpus_needed
    for i in sorted(range(len(free_gpus)), key=lambda i: (-free_gpus[i], i)):
        if left == 0:
            break
        take = min(free_gpus[i], left)
        if take:
            plan[i] = take
            left -= take
    return plan

def run_cost(gpu_hours, on_demand_price, spot_discount_pct, spot_share_pct, failure_overhead_pct):
    hours = gpu_hours * (1 + failure_overhead_pct / 100)
    spot = hours * spot_share_pct / 100
    cost = spot * on_demand_price * (1 - spot_discount_pct / 100) + (hours - spot) * on_demand_price
    return round(cost, 2)

def plan_training(params, gpus, gpu_gb, activation_gb):
    per_param = [16, 4 + 12 / gpus, 2 + 14 / gpus, 16 / gpus]
    for stage, b in enumerate(per_param):
        total = b * params / 1e9 + activation_gb
        if total <= gpu_gb:
            return {'stage': stage, 'per_gpu_gb': round(total, 1)}
    return {'stage': None, 'per_gpu_gb': round(per_param[3] * params / 1e9 + activation_gb, 1)}

import math


def run_report(log):
    if not log:
        return {'steps': 0, 'final_loss': None, 'best_loss': None, 'nan_steps': [], 'tokens_per_sec': 0}
    good = [e['loss'] for e in log if not math.isnan(e['loss'])]
    last = log[-1]['loss']
    return {
        'steps': len(log),
        'final_loss': None if math.isnan(last) else round(last, 4),
        'best_loss': round(min(good), 4) if good else None,
        'nan_steps': [e['step'] for e in log if math.isnan(e['loss'])],
        'tokens_per_sec': int(round(sum(e['tokens'] for e in log) / sum(e['seconds'] for e in log))),
    }
